
# Differential expression analysis of liver vs lung metastases
# Input files are generated by main.py in Data/Processed/.

suppressPackageStartupMessages({
  library(DESeq2)
})

# Always run this script from the repository root.
counts_file <- file.path("Data", "Processed", "DE_counts.csv")
metadata_file <- file.path("Data", "Processed", "DE_metadata.csv")

if (!file.exists(counts_file) || !file.exists(metadata_file)) {
  stop(
    "Input files were not found. Run main.py first to generate ",
    "Data/Processed/DE_counts.csv and DE_metadata.csv."
  )
}

counts <- read.csv(counts_file, check.names = FALSE)
meta <- read.csv(metadata_file, check.names = FALSE)

required_count_columns <- c("Geneid", "gene_name")
required_meta_columns <- c("Sample", "Patient", "Tissue")

if (!all(required_count_columns %in% colnames(counts))) {
  stop("The count file must contain Geneid and gene_name columns.")
}

if (!all(required_meta_columns %in% colnames(meta))) {
  stop("The metadata file must contain Sample, Patient, and Tissue columns.")
}

if (anyDuplicated(counts$Geneid)) {
  stop("Duplicate Geneid values found. Resolve duplicates before DESeq2.")
}

rownames(counts) <- counts$Geneid

count_matrix <- as.matrix(
  counts[, !colnames(counts) %in% c("Geneid", "gene_name"), drop = FALSE]
)

if (!all(colnames(count_matrix) %in% meta$Sample)) {
  stop("Some count-matrix samples are missing from metadata.")
}

if (!all(meta$Sample %in% colnames(count_matrix))) {
  stop("Some metadata samples are missing from the count matrix.")
}

rownames(meta) <- meta$Sample
meta <- meta[colnames(count_matrix), , drop = FALSE]

if (!all(rownames(meta) == colnames(count_matrix))) {
  stop("Sample order does not match between counts and metadata.")
}

if (anyNA(count_matrix) || any(count_matrix < 0)) {
  stop("Count matrix contains missing or negative values.")
}

if (any(count_matrix != round(count_matrix))) {
  stop("DESeq2 requires integer-valued raw counts.")
}

storage.mode(count_matrix) <- "integer"

meta$Patient <- factor(meta$Patient)
meta$Tissue <- factor(meta$Tissue, levels = c("Lung", "Liver"))

if (anyNA(meta$Patient) || anyNA(meta$Tissue)) {
  stop("Patient or Tissue contains missing/unrecognized values.")
}

cat("Count matrix dimensions:", dim(count_matrix), "\n")
cat("Metadata dimensions:", dim(meta), "\n")
cat("\nPatient x Tissue table:\n")
print(table(meta$Patient, meta$Tissue))

# Paired design: account for patient and tissue.
dds <- DESeqDataSetFromMatrix(
  countData = count_matrix,
  colData = meta,
  design = ~ Patient + Tissue
)

# Remove genes with zero counts across all samples.
keep <- rowSums(counts(dds)) > 0
cat("Genes before filtering:", nrow(dds), "\n")
cat("Genes removed:", sum(!keep), "\n")
dds <- dds[keep, ]

# Run DESeq2 and compare Liver against Lung.
dds <- DESeq(dds)

res <- results(
  dds,
  contrast = c("Tissue", "Liver", "Lung"),
  alpha = 0.05
)

res_df <- as.data.frame(res)
res_df$Geneid <- rownames(res_df)

gene_annotation <- counts[, c("Geneid", "gene_name")]
res_df <- merge(
  res_df,
  gene_annotation,
  by = "Geneid",
  all.x = TRUE,
  sort = FALSE
)

res_df <- res_df[, c(
  "Geneid", "gene_name", "baseMean", "log2FoldChange",
  "lfcSE", "stat", "pvalue", "padj"
)]

res_df <- res_df[order(res_df$padj, na.last = TRUE), ]

significant <- res_df[
  !is.na(res_df$padj) & res_df$padj < 0.05,
]

cat("\nSignificant genes (padj < 0.05):", nrow(significant), "\n")
cat("Higher in Liver:", sum(significant$log2FoldChange > 0), "\n")
cat("Higher in Lung:", sum(significant$log2FoldChange < 0), "\n")

# Create output directories.
results_dir <- file.path("Results", "Differential_Expression")
deseq_dir <- file.path("Results", "DESeq2")

dir.create(results_dir, recursive = TRUE, showWarnings = FALSE)
dir.create(deseq_dir, recursive = TRUE, showWarnings = FALSE)

write.csv(
  res_df,
  file.path(results_dir, "Liver_vs_Lung_DESeq2_all_genes.csv"),
  row.names = FALSE
)

write.csv(
  significant,
  file.path(results_dir, "Liver_vs_Lung_DESeq2_significant_genes.csv"),
  row.names = FALSE
)

write.csv(
  head(significant, 20),
  file.path(results_dir, "Top20_DE_genes.csv"),
  row.names = FALSE
)

saveRDS(dds, file.path(deseq_dir, "dds.rds"))

cat("\nDifferential expression analysis completed.\n")
